r=Path('/home/yndx/zxk/rul');o=r/'experiments/cpmlp_hust_recipe_adapt_seed42_v2';rec=json.loads((o/'completion_receipt.json').read_text());assert rec['status'] in ['EARLY_STOP_COMPLETED','MAX_EPOCHS_COMPLETED'];p=o/rec['selected_prediction_file'];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assert sha(p)==rec['predictions_sha256'];rows=list(csv.DictReader(p.open()));ids=sorted({x['file_name'] for x in rows});assert len(ids)==15 and len(rows)==1500
